SourceCode.Declaration:
/// <summary>
/// The warehouse the signed-in user picked in the Mobile operations workspace filter. Empty means
/// every store the user may see. Kept per user in the AOS global object cache, so it lasts until the
/// AOS restarts. The tile queries read it through HSMobileOpsWorkspaceScope.
/// </summary>
public final class HSMobileOpsWorkspaceFilter
{
    private const str CacheOwner = 'HSMobileOpsWorkspaceFilter';
}

Method.Source:
private static SysGlobalObjectCache cache()
{
    if (classfactory)
    {
        return classfactory.globalObjectCache();
    }

    // The class factory is not initialised when a query range function runs under IL.
    return new SysGlobalObjectCache();
}

/// <summary>
/// The warehouse picked by the signed-in user, or an empty string for no filter.
/// </summary>
public static str current()
{
    container value = HSMobileOpsWorkspaceFilter::cache().find(HSMobileOpsWorkspaceFilter::CacheOwner, [curUserId()]);

    return conLen(value) > 0 ? conPeek(value, 1) : '';
}

/// <summary>
/// Remembers the warehouse the signed-in user picked. An empty string clears the filter.
/// </summary>
public static void set(str _warehouseId)
{
    HSMobileOpsWorkspaceFilter::cache().insert(HSMobileOpsWorkspaceFilter::CacheOwner, [curUserId()], [strLRTrim(_warehouseId)]);
}
